-- Lot éditorial Spoontrotter généré par scripts/recipe-batches/build.mjs : 25 recettes, 16 nouveaux lieux.
-- Recettes rédigées pour l'application (adaptations éditoriales) à partir des compositions traditionnelles documentées.
-- Données source : data/recipe-batches/. Photos : Wikimedia Commons, vérifiées une à une (auteur et licence conservés).
-- Chargeur temporaire (pg_temp : disparaît à la fin de la session, jamais exposé à l'API).
create or replace function pg_temp.spoontrotter_import(batch jsonb) returns integer
language plpgsql as $fn$
declare
  r jsonb;
  p jsonb;
  ph jsonb;
  rid uuid;
  country_place uuid;
  place uuid;
  place_name text;
  region_text text;
  source_name constant text := 'Spoontrotter — adaptation éditoriale';
  author constant uuid := 'ac515660-4852-4ebd-8cb5-3348d60e06e9';
  total integer := 0;
begin
  for r in select value from jsonb_array_elements(batch) loop
    select id into country_place from public.culinary_places
      where country_code = r->>'country' and place_type = 'country' order by created_at limit 1;
    if country_place is null then
      raise exception 'Pays absent de l''atlas : %', r->>'country';
    end if;

    p := r->'place';
    if jsonb_typeof(p) = 'object' then
      insert into public.culinary_places (slug, name, country_code, place_type, parent_id, latitude, longitude, default_zoom, summary, is_active)
      values (p->>'slug', p->>'name', r->>'country', p->>'type', country_place, (p->>'lat')::float8, (p->>'lng')::float8,
              coalesce((p->>'zoom')::float8, case when p->>'type' = 'region' then 7 else 9 end), p->>'summary', true)
      on conflict (slug) do nothing;
      select id, name into place, place_name from public.culinary_places where slug = p->>'slug';
    elsif jsonb_typeof(p) = 'string' then
      select id, name into place, place_name from public.culinary_places where slug = p #>> '{}';
      if place is null then
        raise exception 'Lieu absent de l''atlas : %', p #>> '{}';
      end if;
    else
      place := country_place;
      place_name := null;
    end if;

    region_text := coalesce(r->>'region', place_name);
    rid := md5('spoontrotter:recipe:' || (r->>'slug'))::uuid;
    ph := r->'photo';

    insert into public.recipes (id, author_id, title, original_title, slug, description, excerpt, source_language, country_code, region,
      category, authenticity, status, difficulty, prep_minutes, cook_minutes, servings, published_at, primary_place_id,
      is_editorial, is_borderless, source_name, source_url, source_notes)
    values (rid, author, r->>'title', r->>'original', r->>'slug', r->>'desc', r->>'desc', 'fr', r->>'country', region_text,
      r->>'cat', coalesce(r->>'auth', 'adapted')::public.recipe_authenticity, 'published', (r->>'diff')::public.recipe_difficulty,
      (r->>'prep')::int, (r->>'cook')::int, (r->>'serv')::numeric, now(), place,
      true, false, source_name, ph->>'page',
      'Recette éditoriale rédigée pour l’application à partir de la composition traditionnelle documentée du plat.')
    on conflict (id) do update set title = excluded.title, original_title = excluded.original_title, description = excluded.description,
      excerpt = excluded.excerpt, country_code = excluded.country_code, region = excluded.region, category = excluded.category,
      difficulty = excluded.difficulty, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes,
      servings = excluded.servings, primary_place_id = excluded.primary_place_id, source_url = excluded.source_url, updated_at = now();

    delete from public.recipe_ingredients where recipe_id = rid;
    insert into public.recipe_ingredients (recipe_id, position, name, quantity, unit, note)
    select rid, (t.o - 1)::int, t.e->>0, (t.e->>1)::numeric, t.e->>2, t.e->>3
    from jsonb_array_elements(r->'ing') with ordinality as t(e, o);

    delete from public.recipe_steps where recipe_id = rid;
    insert into public.recipe_steps (recipe_id, position, instruction)
    select rid, (t.o - 1)::int, t.s from jsonb_array_elements_text(r->'steps') with ordinality as t(s, o);

    delete from public.recipe_title_translations where recipe_id = rid;
    insert into public.recipe_title_translations (recipe_id, language_code, title, model) values
      (rid, 'fr', r->>'title', 'editorial-seed'),
      (rid, 'en', r->>'en', 'editorial-reviewed'),
      (rid, 'es', r->>'es', 'editorial-reviewed');

    delete from public.recipe_locations where recipe_id = rid;
    insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, place, 'origin', true);
    if place <> country_place then
      insert into public.recipe_locations (recipe_id, place_id, relation, is_primary) values (rid, country_place, 'origin', false);
    end if;

    delete from public.place_specialties where recipe_id = rid;
    insert into public.place_specialties (place_id, recipe_id, name, description, origin_note, is_signature, sort_order, source_name, source_url)
    values (place, rid, r->>'original', r->>'desc', coalesce(region_text, (select name from public.culinary_places where id = country_place)),
            place <> country_place, 10, source_name, ph->>'page');

    delete from public.recipe_images where recipe_id = rid and source_type = 'external_licensed';
    if jsonb_typeof(ph) = 'object' then
      insert into public.recipe_images (recipe_id, source_type, status, external_url, alt_text, source_name, source_page_url,
        photographer_name, license_name, license_url, attribution_text, is_primary, is_representative, moderation_notes)
      values (rid, 'external_licensed', 'ready', ph->>'url', r->>'title', coalesce(ph->>'source', 'Wikimedia Commons'), ph->>'page',
        nullif(ph->>'author', ''), ph->>'license', nullif(ph->>'licenseUrl', ''),
        'Photo : ' || coalesce(nullif(ph->>'author', ''), 'auteur inconnu') || ' · ' || (ph->>'license') || ' · ' || coalesce(ph->>'source', 'Wikimedia Commons'),
        true, true, 'Photo libre vérifiée à l’œil : le fichier représente ce plat.');
    end if;

    total := total + 1;
  end loop;
  return total;
end;
$fn$;
select pg_temp.spoontrotter_import($batch$[{"slug":"takoyaki-osaka","country":"JP","original":"Takoyaki (たこ焼き)","title":"Takoyaki d’Osaka (boulettes de pâte au poulpe)","en":"Osaka takoyaki (octopus balls)","es":"Takoyaki de Osaka (bolitas de pulpo)","desc":"Boulettes de pâte au dashi cuites dans une plaque à alvéoles, garnies de poulpe, gingembre mariné et oignon vert, nappées de sauce, mayonnaise, aonori et bonite séchée.","cat":"Cuisine de rue","diff":"medium","prep":20,"cook":20,"serv":4,"place":"jp-osaka","ing":[["Farine",150,"g",null],["Dashi",500,"ml","froid"],["Œufs",2,null,null],["Sauce soya",1,"c. à thé",null],["Poulpe cuit",150,"g","en dés de 1 cm"],["Gingembre mariné (beni shōga)",2,"c. à soupe","haché"],["Oignons verts",3,null,"émincés"],["Tenkasu (miettes de tempura)",30,"g",null],["Sauce takoyaki",4,"c. à soupe",null],["Mayonnaise japonaise",3,"c. à soupe",null],["Aonori et katsuobushi",1,"portion",null],["Huile",2,"c. à soupe",null]],"steps":["Fouetter farine, dashi, œufs et soya en pâte très liquide.","Chauffer et huiler généreusement la plaque à takoyaki.","Remplir les alvéoles à ras bord et ajouter poulpe, gingembre, oignon vert et tenkasu.","Après 1 minute, retourner chaque boule d’un quart de tour avec une pique en rabattant la pâte débordante.","Continuer à tourner jusqu’à ce que les boules soient rondes et dorées (5 à 6 minutes).","Napper de sauce et de mayonnaise, saupoudrer d’aonori et de katsuobushi."],"photo":{"file":"File:06749jfCuisine Foods Takoyaki cooking Balut Penoy Baliuag Bulacanfvf 01.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/45/06749jfCuisine_Foods_Takoyaki_cooking_Balut_Penoy_Baliuag_Bulacanfvf_01.jpg/1280px-06749jfCuisine_Foods_Takoyaki_cooking_Balut_Penoy_Baliuag_Bulacanfvf_01.jpg","page":"https://commons.wikimedia.org/wiki/File:06749jfCuisine_Foods_Takoyaki_cooking_Balut_Penoy_Baliuag_Bulacanfvf_01.jpg","author":"Judgefloro","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"Wikimedia Commons"}},{"slug":"hiroshima-okonomiyaki","country":"JP","original":"Hiroshima-yaki (広島風お好み焼き)","title":"Okonomiyaki de Hiroshima (crêpe en couches, chou et nouilles)","en":"Hiroshima-style okonomiyaki (layered pancake with noodles)","es":"Okonomiyaki estilo Hiroshima","desc":"Version en couches de l’okonomiyaki : crêpe fine, montagne de chou, porc et nouilles yakisoba, refermée par un œuf et nappée de sauce Otafuku.","cat":"Cuisine de rue","diff":"medium","prep":20,"cook":20,"serv":2,"place":{"slug":"jp-hiroshima","name":"Hiroshima","type":"city","lat":34.3853,"lng":132.4553,"summary":"Ville du Chūgoku réputée pour son okonomiyaki en couches et ses huîtres."},"ing":[["Farine",50,"g",null],["Eau",100,"ml",null],["Chou blanc",300,"g","en fine julienne"],["Germes de soja",80,"g",null],["Poitrine de porc",6,"tranches","fines"],["Nouilles yakisoba",2,"portions",null],["Œufs",2,null,null],["Sauce okonomiyaki",4,"c. à soupe",null],["Oignons verts",2,null,null],["Aonori",1,"c. à thé",null]],"steps":["Étaler une louche de pâte farine-eau en crêpe fine sur la plaque chaude.","Empiler le chou puis les germes de soja et les tranches de porc.","Retourner la pile d’un coup et laisser le chou cuire à la vapeur 5 minutes.","Faire sauter les nouilles à côté avec un peu de sauce et poser la pile dessus.","Casser un œuf à côté, l’étaler et poser la pile dessus; retourner.","Napper de sauce, parsemer d’oignons verts et d’aonori."],"photo":{"file":"File:Hiroshima-Style Okonomiyaki (40283556800).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9b/Hiroshima-Style_Okonomiyaki_%2840283556800%29.jpg/1280px-Hiroshima-Style_Okonomiyaki_%2840283556800%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Hiroshima-Style_Okonomiyaki_(40283556800).jpg","author":"Ajay Suresh from New York, NY, USA","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"hakata-ramen","country":"JP","original":"Hakata ramen (博多ラーメン)","title":"Ramen de Hakata (bouillon tonkotsu laiteux, nouilles fines)","en":"Hakata ramen (Fukuoka tonkotsu ramen)","es":"Ramen de Hakata (tonkotsu de Fukuoka)","desc":"Bouillon d’os de porc bouilli à gros bouillons jusqu’à devenir blanc et crémeux, nouilles très fines et fermes, chashu, gingembre rouge et graines de sésame, spécialité de Fukuoka.","cat":"Soupe","diff":"hard","prep":40,"cook":720,"serv":6,"place":{"slug":"jp-fukuoka","name":"Fukuoka","type":"city","lat":33.5902,"lng":130.4017,"summary":"Grande ville de Kyūshū, dont le quartier de Hakata est le berceau du ramen tonkotsu."},"ing":[["Os de porc (fémurs, pieds)",3,"kg","blanchis"],["Ail",1,"tête",null],["Gingembre",50,"g",null],["Oignons verts",6,null,null],["Sauce soya",100,"ml","pour le tare"],["Sel",2,"c. à soupe",null],["Nouilles ramen fines",6,"portions",null],["Chashu (porc braisé)",12,"tranches",null],["Beni shōga",3,"c. à soupe",null],["Graines de sésame",2,"c. à soupe",null],["Champignons kikurage",50,"g","réhydratés"]],"steps":["Blanchir les os 15 minutes, les rincer et les gratter.","Les couvrir d’eau froide et faire bouillir à gros bouillons 12 heures en rajoutant de l’eau, avec ail et gingembre les 2 dernières heures.","Filtrer : le bouillon doit être opaque et laiteux.","Préparer le tare en mélangeant soya et sel dans chaque bol.","Cuire les nouilles 1 minute (katamen, fermes).","Verser le bouillon brûlant, ajouter nouilles, chashu, kikurage, oignons verts, beni shōga et sésame."],"photo":{"file":"File:Hakata ramen.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ef/Hakata_ramen.JPG/1280px-Hakata_ramen.JPG","page":"https://commons.wikimedia.org/wiki/File:Hakata_ramen.JPG","author":"vigorous_action","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"goya-champuru","country":"JP","original":"Gōyā chanpurū (ゴーヤーチャンプルー)","title":"Gōyā chanpurū d’Okinawa (sauté de margose, tofu et porc)","en":"Okinawan gōyā chanpurū (bitter melon stir-fry)","es":"Gōyā chanpurū de Okinawa","desc":"Sauté de melon amer, tofu ferme, poitrine de porc ou Spam et œuf, plat emblématique de la cuisine familiale d’Okinawa.","cat":"Plat principal","diff":"easy","prep":20,"cook":15,"serv":4,"place":{"slug":"jp-okinawa","name":"Okinawa","type":"island","lat":26.3344,"lng":127.8056,"summary":"Archipel subtropical des Ryūkyū : chanpurū, rafute, soba d’Okinawa."},"ing":[["Melon amer (gōyā)",1,null,"épépiné, en fines demi-lunes"],["Tofu ferme (shima-dōfu)",300,"g","pressé"],["Poitrine de porc ou Spam",150,"g","en lamelles"],["Œufs",2,null,null],["Sauce soya",1,"c. à soupe",null],["Dashi en poudre",1,"c. à thé",null],["Huile",2,"c. à soupe",null],["Katsuobushi",1,"poignée",null],["Sel",0.5,"c. à thé","pour dégorger"]],"steps":["Saler le gōyā 10 minutes, le rincer et l’essorer pour réduire l’amertume.","Faire dorer le tofu en morceaux dans l’huile; réserver.","Sauter le porc, puis ajouter le gōyā 2 minutes.","Remettre le tofu, assaisonner de soya et de dashi.","Verser les œufs battus et mélanger jusqu’à ce qu’ils prennent.","Servir parsemé de katsuobushi."],"photo":{"file":"File:Goya chanpuru - Okinawan food - June 14 2015.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/39/Goya_chanpuru_-_Okinawan_food_-_June_14_2015.jpg/1280px-Goya_chanpuru_-_Okinawan_food_-_June_14_2015.jpg","page":"https://commons.wikimedia.org/wiki/File:Goya_chanpuru_-_Okinawan_food_-_June_14_2015.jpg","author":"Nesnad","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","source":"Wikimedia Commons"}},{"slug":"hitsumabushi-nagoya","country":"JP","original":"Hitsumabushi (ひつまぶし)","title":"Hitsumabushi de Nagoya (anguille grillée sur riz, en trois façons)","en":"Nagoya hitsumabushi (grilled eel over rice, eaten three ways)","es":"Hitsumabushi de Nagoya (anguila a la parrilla sobre arroz)","desc":"Anguille grillée laquée à la sauce tare, coupée en lanières sur du riz dans un bol en bois, mangée nature, puis avec condiments, puis en ochazuke au dashi.","cat":"Riz","diff":"medium","prep":20,"cook":20,"serv":2,"place":{"slug":"jp-nagoya","name":"Nagoya","type":"city","lat":35.1815,"lng":136.9066,"summary":"Métropole de la région de Chūbu : hitsumabushi, tebasaki, miso katsu."},"ing":[["Filets d’anguille (unagi) grillés",2,null,null],["Riz japonais cuit",400,"g",null],["Sauce soya",4,"c. à soupe",null],["Mirin",4,"c. à soupe",null],["Sucre",2,"c. à soupe",null],["Saké",2,"c. à soupe",null],["Oignons verts",2,null,"émincés"],["Wasabi",1,"c. à thé",null],["Nori",1,"feuille","en lanières"],["Dashi chaud",400,"ml",null]],"steps":["Réduire soya, mirin, sucre et saké en sauce tare sirupeuse.","Badigeonner l’anguille de tare et la griller au gril jusqu’à caramélisation, deux fois.","Mélanger le riz chaud avec une cuillère de tare.","Le mettre dans le bol, couvrir d’anguille coupée en lanières.","Diviser en quatre : manger un quart nature, un quart avec oignons verts, wasabi et nori.","Arroser le troisième quart de dashi chaud (ochazuke) et finir le dernier à sa préférence."],"photo":{"file":"File:Hitsumabushi by hirotomo in Nagoya.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/3/32/Hitsumabushi_by_hirotomo_in_Nagoya.jpg","page":"https://commons.wikimedia.org/wiki/File:Hitsumabushi_by_hirotomo_in_Nagoya.jpg","author":"hirotomo from Nagoya","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"tebasaki-nagoya","country":"JP","original":"Tebasaki (手羽先)","title":"Tebasaki de Nagoya (ailes de poulet frites, laque sucrée-poivrée)","en":"Nagoya tebasaki (glazed peppery chicken wings)","es":"Tebasaki de Nagoya (alitas de pollo glaseadas)","desc":"Ailes de poulet frites deux fois sans panure, laquées d’une sauce soya-mirin sucrée et couvertes de poivre noir et de sésame.","cat":"Cuisine de rue","diff":"easy","prep":15,"cook":25,"serv":4,"place":{"slug":"jp-nagoya","name":"Nagoya","type":"city","lat":35.1815,"lng":136.9066,"summary":"Métropole de la région de Chūbu : hitsumabushi, tebasaki, miso katsu."},"ing":[["Ailes de poulet",1,"kg",null],["Huile de friture",1,"l",null],["Sauce soya",4,"c. à soupe",null],["Mirin",3,"c. à soupe",null],["Sucre",1,"c. à soupe",null],["Saké",2,"c. à soupe",null],["Ail râpé",1,"c. à thé",null],["Poivre noir",2,"c. à thé","moulu grossièrement"],["Graines de sésame",1,"c. à soupe",null]],"steps":["Sécher soigneusement les ailes.","Réduire soya, mirin, sucre, saké et ail en sauce légèrement sirupeuse.","Frire les ailes 8 minutes à 160 °C, laisser reposer 5 minutes.","Les refrire 2 minutes à 190 °C pour les rendre croustillantes.","Les badigeonner aussitôt de sauce.","Saupoudrer généreusement de poivre et de sésame."],"photo":{"file":"File:Furaibo Tebasaki.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Furaibo_Tebasaki.JPG/1280px-Furaibo_Tebasaki.JPG","page":"https://commons.wikimedia.org/wiki/File:Furaibo_Tebasaki.JPG","author":"Nissy-KITAQ","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"jingisukan-hokkaido","country":"JP","original":"Jingisukan (ジンギスカン)","title":"Jingisukan de Hokkaidō (agneau grillé sur dôme de fonte)","en":"Hokkaido jingisukan (grilled lamb on a dome skillet)","es":"Jingisukan de Hokkaido (cordero a la plancha)","desc":"Agneau ou mouton mariné grillé sur une plaque bombée, les légumes cuisant dans le jus qui coule sur les bords, plat convivial de Hokkaidō.","cat":"Grillade","diff":"easy","prep":20,"cook":20,"serv":4,"place":"jp-hokkaido","ing":[["Épaule d’agneau",700,"g","en tranches fines"],["Sauce soya",5,"c. à soupe",null],["Pomme",0.5,null,"râpée"],["Oignon",0.5,null,"râpé"],["Ail et gingembre",1,"c. à soupe","râpés"],["Mirin et sucre",2,"c. à soupe",null],["Germes de soja",200,"g",null],["Chou",0.25,null,"en morceaux"],["Oignon",1,null,"en rondelles"],["Potiron",200,"g","en tranches"],["Graisse de mouton ou huile",1,"c. à soupe",null]],"steps":["Mélanger soya, pomme, oignon, ail, gingembre, mirin et sucre.","Mariner l’agneau 1 heure.","Chauffer la plaque bombée et la graisser.","Disposer les légumes sur les bords et l’agneau au sommet.","Griller la viande 1 à 2 minutes par côté en laissant le jus arroser les légumes.","Servir au fur et à mesure avec du riz."],"photo":{"file":"File:Jingisukan at Asahi Beer Community Hall.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e9/Jingisukan_at_Asahi_Beer_Community_Hall.jpg/1280px-Jingisukan_at_Asahi_Beer_Community_Hall.jpg","page":"https://commons.wikimedia.org/wiki/File:Jingisukan_at_Asahi_Beer_Community_Hall.jpg","author":"mdid","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"yudofu-kyoto","country":"JP","original":"Yudōfu (湯豆腐)","title":"Yudōfu de Kyōto (tofu mijoté au kombu)","en":"Kyoto yudōfu (simmered tofu in kombu broth)","es":"Yudōfu de Kioto (tofu en caldo de kombu)","desc":"Tofu soyeux chauffé doucement dans un bouillon de kombu, trempé dans une sauce soya-yuzu, plat végétarien des temples zen de Kyōto.","cat":"Plat principal","diff":"easy","prep":10,"cook":20,"serv":2,"place":{"slug":"jp-kyoto","name":"Kyōto","type":"city","lat":35.0116,"lng":135.7681,"summary":"Ancienne capitale impériale : cuisine kaiseki, tofu, yuba et matcha."},"ing":[["Tofu soyeux de qualité",600,"g","en gros cubes"],["Kombu",15,"g",null],["Eau",1,"l",null],["Sauce soya",4,"c. à soupe",null],["Mirin",1,"c. à soupe",null],["Jus de yuzu ou citron",1,"c. à soupe",null],["Oignons verts",2,null,"émincés"],["Gingembre râpé",1,"c. à thé",null],["Katsuobushi",1,"poignée","facultatif"]],"steps":["Faire tremper le kombu 30 minutes dans l’eau du donabe.","Chauffer doucement sans bouillir.","Ajouter le tofu et le laisser chauffer 5 minutes jusqu’à ce qu’il frémisse.","Mélanger soya, mirin et yuzu pour la sauce de trempage.","Servir chaque convive à l’écumoire.","Tremper le tofu dans la sauce avec oignons verts et gingembre."],"photo":{"file":"File:110115 Ryoan-ji Kyoto Japan08s3.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c7/110115_Ryoan-ji_Kyoto_Japan08s3.jpg/1280px-110115_Ryoan-ji_Kyoto_Japan08s3.jpg","page":"https://commons.wikimedia.org/wiki/File:110115_Ryoan-ji_Kyoto_Japan08s3.jpg","author":"663highland","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"peking-duck","country":"CN","original":"Běijīng kǎoyā (北京烤鸭)","title":"Canard laqué de Pékin (peau croustillante, crêpes et sauce hoisin)","en":"Peking roast duck","es":"Pato laqueado de Pekín","desc":"Canard gonflé d’air, ébouillanté, laqué au maltose et séché avant d’être rôti jusqu’à ce que la peau soit croustillante, découpé et roulé dans de fines crêpes avec ciboule et sauce.","cat":"Plat principal","diff":"hard","prep":60,"cook":75,"serv":6,"place":{"slug":"cn-beijing","name":"Pékin","type":"city","lat":39.9042,"lng":116.4074,"summary":"Capitale chinoise : canard laqué, zhajiangmian et jiaozi."},"ing":[["Canard entier",2.5,"kg",null],["Maltose ou miel",3,"c. à soupe",null],["Vinaigre de riz",2,"c. à soupe",null],["Cinq-épices",1,"c. à thé",null],["Sel",1,"c. à soupe",null],["Crêpes mandarin",24,null,null],["Sauce hoisin ou sauce tianmian",100,"ml",null],["Ciboules",6,null,"en julienne"],["Concombre",1,null,"en bâtonnets"]],"steps":["Frotter l’intérieur du canard de sel et de cinq-épices.","L’ébouillanter pour tendre la peau, puis le badigeonner de maltose dilué au vinaigre.","Le suspendre 24 heures au frais et au sec pour sécher la peau.","Rôtir 1 heure 15 à 200 °C sur une grille au-dessus d’un plat d’eau.","Découper la peau et la viande en fines tranches.","Rouler dans les crêpes chaudes avec sauce, ciboule et concombre."],"photo":{"file":"File:Bianyifang duck.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/48/Bianyifang_duck.jpg/1280px-Bianyifang_duck.jpg","page":"https://commons.wikimedia.org/wiki/File:Bianyifang_duck.jpg","author":"vixyao","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"zhajiangmian-beijing","country":"CN","original":"Zhájiàngmiàn (炸酱面)","title":"Zhajiangmian de Pékin (nouilles à la sauce de soja fermentée et porc)","en":"Beijing zhajiangmian (noodles with fried soybean paste)","es":"Zhajiangmian de Pekín (fideos con salsa de soja fermentada)","desc":"Nouilles de blé épaisses servies avec une sauce de porc frit dans la pâte de soja jaune et la sauce tianmian, et une garniture de légumes crus en julienne.","cat":"Plat principal","diff":"easy","prep":20,"cook":25,"serv":4,"place":{"slug":"cn-beijing","name":"Pékin","type":"city","lat":39.9042,"lng":116.4074,"summary":"Capitale chinoise : canard laqué, zhajiangmian et jiaozi."},"ing":[["Nouilles de blé épaisses",500,"g",null],["Poitrine de porc",300,"g","en petits dés"],["Pâte de soja jaune (huangjiang)",3,"c. à soupe",null],["Sauce tianmian",3,"c. à soupe",null],["Ciboule",2,null,"hachée"],["Gingembre",1,"c. à soupe","haché"],["Concombre",1,null,"en julienne"],["Radis",4,null,"en julienne"],["Germes de soja",100,"g","blanchis"],["Huile",3,"c. à soupe",null]],"steps":["Faire rendre le gras du porc dans l’huile à feu moyen.","Ajouter gingembre et ciboule.","Ajouter les deux pâtes délayées dans 100 ml d’eau et frire 15 minutes à feu doux en remuant.","Cuire les nouilles et les rincer.","Disposer nouilles et légumes en julienne dans les bols.","Ajouter une grosse cuillère de sauce et mélanger à table."],"photo":{"file":"File:Fried sauce noodles in Ganjiakou (20140302144640).JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/Fried_sauce_noodles_in_Ganjiakou_%2820140302144640%29.JPG/1280px-Fried_sauce_noodles_in_Ganjiakou_%2820140302144640%29.JPG","page":"https://commons.wikimedia.org/wiki/File:Fried_sauce_noodles_in_Ganjiakou_(20140302144640).JPG","author":"N509FZ","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"xiaolongbao-shanghai","country":"CN","original":"Xiǎolóngbāo (小笼包)","title":"Xiaolongbao de Shanghai (raviolis vapeur remplis de bouillon)","en":"Shanghai xiaolongbao (soup dumplings)","es":"Xiaolongbao de Shanghái (empanadillas de sopa)","desc":"Petits raviolis plissés cuits à la vapeur en panier de bambou, renfermant une farce de porc et un bouillon gélifié qui fond à la cuisson; nés à Nanxiang près de Shanghai.","cat":"Pâtes farcies","diff":"hard","prep":120,"cook":10,"serv":4,"place":"cn-shanghai","ing":[["Farine",250,"g",null],["Eau tiède",130,"ml",null],["Porc haché gras",300,"g",null],["Aspic de bouillon de porc (gelée)",200,"g","en petits dés"],["Sauce soya",1,"c. à soupe",null],["Vin de Shaoxing",1,"c. à soupe",null],["Gingembre",1,"c. à soupe","haché"],["Huile de sésame",1,"c. à thé",null],["Sucre",1,"c. à thé",null],["Vinaigre noir et gingembre",1,"portion","pour tremper"]],"steps":["Préparer la veille un bouillon de couennes de porc réduit qui prend en gelée.","Mélanger porc, soya, Shaoxing, gingembre, sésame et sucre; incorporer la gelée en dés.","Pétrir farine et eau; reposer 30 minutes.","Diviser en boules de 10 g et étaler en disques fins sur les bords.","Garnir et plisser en 18 plis environ.","Cuire 8 minutes à la vapeur sur papier ou feuilles de chou; servir avec vinaigre noir au gingembre."],"photo":{"file":"File:2019-02-22 Xiaolongbao in \"Taste Of Shanghai\" restaurant, Sydney, Australia.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/35/2019-02-22_Xiaolongbao_in_%22Taste_Of_Shanghai%22_restaurant%2C_Sydney%2C_Australia.jpg/1280px-2019-02-22_Xiaolongbao_in_%22Taste_Of_Shanghai%22_restaurant%2C_Sydney%2C_Australia.jpg","page":"https://commons.wikimedia.org/wiki/File:2019-02-22_Xiaolongbao_in_%22Taste_Of_Shanghai%22_restaurant,_Sydney,_Australia.jpg","author":"Maksym Kozlenko","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"hong-shao-rou-shanghai","country":"CN","original":"Hóngshāoròu (红烧肉)","title":"Hong shao rou de Shanghai (poitrine de porc braisée au sucre et soya)","en":"Shanghai-style hong shao rou (red-braised pork belly)","es":"Hong shao rou (panceta estofada en rojo)","desc":"Cubes de poitrine de porc caramélisés puis braisés au vin de Shaoxing, sauce soya et sucre candi jusqu’à devenir fondants et laqués.","cat":"Plat principal","diff":"medium","prep":15,"cook":90,"serv":4,"place":"cn-shanghai","ing":[["Poitrine de porc avec couenne",700,"g","en cubes de 3 cm"],["Sucre candi",40,"g",null],["Vin de Shaoxing",100,"ml",null],["Sauce soya claire",2,"c. à soupe",null],["Sauce soya foncée",1,"c. à soupe",null],["Gingembre",4,"tranches",null],["Ciboules",3,null,null],["Badiane",2,null,null],["Huile",1,"c. à soupe",null]],"steps":["Blanchir le porc 3 minutes et l’égoutter.","Faire fondre le sucre candi dans l’huile jusqu’à caramel ambré.","Enrober le porc de caramel.","Ajouter gingembre, ciboule, badiane, Shaoxing, sauces soya et eau chaude à hauteur.","Mijoter 1 heure à couvert à feu doux.","Découvrir et réduire à feu vif jusqu’à ce que la sauce laque les morceaux."],"photo":{"file":"File:Red braised pork belly 红烧肉 hóngshāoròu 23 January 2025 Filipinas4.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f9/Red_braised_pork_belly_%E7%BA%A2%E7%83%A7%E8%82%89_h%C3%B3ngsh%C4%81or%C3%B2u_23_January_2025_Filipinas4.jpg/1280px-Red_braised_pork_belly_%E7%BA%A2%E7%83%A7%E8%82%89_h%C3%B3ngsh%C4%81or%C3%B2u_23_January_2025_Filipinas4.jpg","page":"https://commons.wikimedia.org/wiki/File:Red_braised_pork_belly_%E7%BA%A2%E7%83%A7%E8%82%89_h%C3%B3ngsh%C4%81or%C3%B2u_23_January_2025_Filipinas4.jpg","author":"","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"dan-dan-mian","country":"CN","original":"Dàndànmiàn (担担面)","title":"Dan dan mian de Chengdu (nouilles épicées au porc et poivre du Sichuan)","en":"Chengdu dan dan noodles","es":"Fideos dan dan de Chengdu","desc":"Nouilles nappées d’une sauce à l’huile pimentée, au poivre du Sichuan, au légume salé ya cai et au porc haché croustillant, autrefois vendues à la palanche (dan).","cat":"Cuisine de rue","diff":"medium","prep":15,"cook":15,"serv":4,"place":"cn-chengdu","ing":[["Nouilles de blé fines",400,"g",null],["Porc haché",200,"g",null],["Ya cai (légume salé du Sichuan)",2,"c. à soupe",null],["Sauce soya",3,"c. à soupe",null],["Huile pimentée",4,"c. à soupe",null],["Poivre du Sichuan moulu",1,"c. à thé","torréfié"],["Vinaigre noir",1,"c. à soupe",null],["Pâte de sésame",1,"c. à soupe","facultatif"],["Ciboule",2,null,"hachée"],["Bok choy",4,null,"blanchis"]],"steps":["Faire frire le porc jusqu’à ce qu’il soit sec et croustillant; ajouter le ya cai et 1 cuillère de soya.","Répartir dans les bols la soya, l’huile pimentée, le poivre du Sichuan, le vinaigre et la pâte de sésame.","Cuire les nouilles et le bok choy.","Ajouter une louche d’eau de cuisson dans chaque bol.","Déposer les nouilles, le porc et le bok choy.","Parsemer de ciboule et mélanger avant de manger."],"photo":{"file":"File:Dandanmian in Chengdu (20180218142856).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/49/Dandanmian_in_Chengdu_%2820180218142856%29.jpg/1280px-Dandanmian_in_Chengdu_%2820180218142856%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Dandanmian_in_Chengdu_(20180218142856).jpg","author":"N509FZ","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"biangbiang-mian","country":"CN","original":"Biángbiáng miàn (𰻞𰻞面)","title":"Biang biang mian de Xi’an (larges nouilles tirées, huile pimentée)","en":"Xi’an biang biang noodles","es":"Fideos biang biang de Xi’an","desc":"Nouilles très larges tirées à la main et claquées sur le plan de travail, garnies d’ail, piment et ciboule arrosés d’huile fumante, plat du Shaanxi.","cat":"Plat principal","diff":"medium","prep":40,"cook":10,"serv":3,"place":{"slug":"cn-xian","name":"Xi’an","type":"city","lat":34.3416,"lng":108.9398,"summary":"Capitale du Shaanxi et ancienne capitale impériale : biang biang mian, roujiamo, quartier musulman."},"ing":[["Farine",400,"g",null],["Eau",220,"ml",null],["Sel",1,"c. à thé",null],["Ail",4,"gousses","haché"],["Flocons de piment",2,"c. à soupe",null],["Ciboule",2,null,"hachée"],["Huile neutre",80,"ml","fumante"],["Sauce soya",2,"c. à soupe",null],["Vinaigre noir",2,"c. à soupe",null],["Bok choy",3,null,"blanchis"]],"steps":["Pétrir farine, eau et sel; reposer 2 heures enrobé d’huile.","Diviser en pâtons, les aplatir en rectangles.","Tirer chaque bande en la claquant sur le plan de travail jusqu’à 1 mètre de long et la déchirer au centre.","Cuire 2 minutes dans l’eau bouillante avec le bok choy.","Mettre dans un bol avec soya et vinaigre, couvrir d’ail, piment et ciboule.","Verser l’huile fumante dessus et mélanger."],"photo":{"file":"File:Biang Biang Mian.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/Biang_Biang_Mian.jpg/1280px-Biang_Biang_Mian.jpg","page":"https://commons.wikimedia.org/wiki/File:Biang_Biang_Mian.jpg","author":"Gary Soup","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"roujiamo-xian","country":"CN","original":"Ròujiāmó (肉夹馍)","title":"Roujiamo de Xi’an (pain plat garni de porc braisé)","en":"Xi’an roujiamo (Chinese braised pork sandwich)","es":"Roujiamo de Xi’an (bocadillo de cerdo estofado)","desc":"Galette baijimo croustillante fourrée de porc braisé longuement aux épices puis haché avec son jus, souvent appelée « hamburger chinois ».","cat":"Cuisine de rue","diff":"medium","prep":40,"cook":150,"serv":6,"place":{"slug":"cn-xian","name":"Xi’an","type":"city","lat":34.3416,"lng":108.9398,"summary":"Capitale du Shaanxi et ancienne capitale impériale : biang biang mian, roujiamo, quartier musulman."},"ing":[["Poitrine de porc",800,"g",null],["Sauce soya",4,"c. à soupe",null],["Sucre candi",20,"g",null],["Vin de Shaoxing",3,"c. à soupe",null],["Badiane, cannelle, laurier, poivre du Sichuan",1,"portion",null],["Gingembre",4,"tranches",null],["Farine",400,"g",null],["Levure sèche",4,"g",null],["Eau tiède",230,"ml",null],["Piment vert",1,null,"haché, facultatif"]],"steps":["Braiser le porc 2 heures dans l’eau avec soya, sucre, Shaoxing, gingembre et épices.","Pétrir farine, levure et eau; lever 1 heure.","Façonner des disques de pâte en spirale épais de 1,5 cm.","Les cuire à sec dans une poêle 3 minutes par face, puis 8 minutes au four à 200 °C.","Hacher le porc avec un peu de jus et le piment.","Ouvrir les pains sur le côté et les farcir généreusement."],"photo":{"file":"File:Roujiamo-cn.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/d/da/Roujiamo-cn.jpg","page":"https://commons.wikimedia.org/wiki/File:Roujiamo-cn.jpg","author":"P. Xie","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","source":"Wikimedia Commons"}},{"slug":"lanzhou-beef-noodles","country":"CN","original":"Lánzhōu niúròu lāmiàn (兰州牛肉拉面)","title":"Nouilles au bœuf de Lanzhou (bouillon clair, nouilles tirées)","en":"Lanzhou beef noodle soup","es":"Fideos de ternera de Lanzhou","desc":"Nouilles tirées à la main dans un bouillon de bœuf clair aux épices, garnies de fines tranches de bœuf, radis blanc, coriandre, ciboule et huile pimentée, cuisine hui du Gansu.","cat":"Soupe","diff":"hard","prep":40,"cook":180,"serv":4,"place":{"slug":"cn-lanzhou","name":"Lanzhou","type":"city","lat":36.0611,"lng":103.8343,"summary":"Capitale du Gansu sur le fleuve Jaune, berceau du lamian au bœuf."},"ing":[["Jarret de bœuf",800,"g",null],["Os de bœuf",1,"kg",null],["Radis blanc",300,"g","en tranches"],["Badiane, poivre du Sichuan, cannelle, cardamome noire",1,"portion",null],["Gingembre",30,"g",null],["Nouilles tirées ou nouilles fraîches",500,"g",null],["Huile pimentée",4,"c. à soupe",null],["Coriandre et ciboule",1,"portion","hachées"],["Sel",2,"c. à thé",null]],"steps":["Faire tremper le bœuf et les os 2 heures pour retirer le sang.","Les cuire 3 heures à frémissement en écumant, avec les épices en sachet et le gingembre.","Retirer le bœuf et le trancher finement; filtrer le bouillon.","Cuire le radis dans le bouillon 10 minutes; saler.","Cuire les nouilles et les répartir dans les bols.","Verser le bouillon, ajouter bœuf, radis, coriandre, ciboule et huile pimentée."],"photo":{"file":"File:Lanzhou beef lamian (20150227145650).JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/53/Lanzhou_beef_lamian_%2820150227145650%29.JPG/1280px-Lanzhou_beef_lamian_%2820150227145650%29.JPG","page":"https://commons.wikimedia.org/wiki/File:Lanzhou_beef_lamian_(20150227145650).JPG","author":"N509FZ","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"char-siu-cantonais","country":"CN","original":"Chāshāo (叉烧)","title":"Char siu cantonais (porc laqué rouge au miel)","en":"Cantonese char siu (honey barbecued pork)","es":"Char siu cantonés (cerdo laqueado con miel)","desc":"Échine de porc marinée à la sauce hoisin, tofu fermenté rouge et cinq-épices, rôtie et laquée au miel jusqu’à des bords caramélisés.","cat":"Grillade","diff":"medium","prep":20,"cook":45,"serv":6,"place":"cn-guangdong","ing":[["Échine de porc",1,"kg","en lanières épaisses"],["Sauce hoisin",4,"c. à soupe",null],["Tofu fermenté rouge",2,"morceaux",null],["Sauce soya",2,"c. à soupe",null],["Vin de Shaoxing",2,"c. à soupe",null],["Sucre",3,"c. à soupe",null],["Cinq-épices",0.5,"c. à thé",null],["Ail",3,"gousses",null],["Miel",3,"c. à soupe","pour laquer"]],"steps":["Mélanger hoisin, tofu fermenté écrasé, soya, Shaoxing, sucre, cinq-épices et ail.","Mariner le porc une nuit.","Disposer sur une grille au-dessus d’un plat d’eau.","Rôtir 25 minutes à 200 °C.","Badigeonner de miel mélangé à la marinade et rôtir encore 15 minutes en retournant.","Finir 2 minutes sous le gril pour caraméliser les bords; trancher."],"photo":{"file":"File:Char Siu by daxiang stef.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/0/08/Char_Siu_by_daxiang_stef.jpg","page":"https://commons.wikimedia.org/wiki/File:Char_Siu_by_daxiang_stef.jpg","author":"daxiang stef","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"har-gow","country":"CN","original":"Xiājiǎo / Har gow (虾饺)","title":"Har gow cantonais (raviolis translucides aux crevettes)","en":"Cantonese har gow (crystal shrimp dumplings)","es":"Har gow cantonés (empanadillas de gamba)","desc":"Raviolis vapeur à la pâte translucide d’amidon de blé et de tapioca, farcis de crevettes et pousses de bambou, pièce maîtresse du dim sum de Canton.","cat":"Pâtes farcies","diff":"hard","prep":60,"cook":8,"serv":4,"place":"cn-guangdong","ing":[["Amidon de blé",100,"g",null],["Fécule de tapioca",30,"g",null],["Eau bouillante",130,"ml",null],["Saindoux ou huile",1,"c. à soupe",null],["Crevettes décortiquées",300,"g",null],["Pousses de bambou",50,"g","hachées finement"],["Huile de sésame",1,"c. à thé",null],["Sucre",0.5,"c. à thé",null],["Sel",0.5,"c. à thé",null],["Poivre blanc",1,"pincée",null]],"steps":["Hacher grossièrement la moitié des crevettes et laisser l’autre en morceaux.","Mélanger avec bambou, sésame, sucre, sel, poivre; réfrigérer.","Verser l’eau bouillante sur les amidons, mélanger, ajouter le saindoux et pétrir.","Diviser en boules de 10 g et les aplatir en disques fins à la lame de couperet.","Garnir et plisser en éventail (10 à 12 plis).","Cuire 6 à 7 minutes à la vapeur vive jusqu’à transparence."],"photo":{"file":"File:Ha Gow (Cantonese Shrimp Dumplings).jpeg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/60/Ha_Gow_%28Cantonese_Shrimp_Dumplings%29.jpeg/1280px-Ha_Gow_%28Cantonese_Shrimp_Dumplings%29.jpeg","page":"https://commons.wikimedia.org/wiki/File:Ha_Gow_(Cantonese_Shrimp_Dumplings).jpeg","author":"ZhengZhou","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"dongpo-rou-hangzhou","country":"CN","original":"Dōngpō ròu (东坡肉)","title":"Porc Dongpo de Hangzhou (poitrine braisée au vin jaune)","en":"Hangzhou Dongpo pork","es":"Cerdo Dongpo de Hangzhou","desc":"Carrés de poitrine de porc braisés plusieurs heures dans le vin de Shaoxing et la sauce soya, puis cuits à la vapeur jusqu’à être fondants, plat attribué au poète Su Dongpo.","cat":"Plat principal","diff":"medium","prep":20,"cook":180,"serv":4,"place":{"slug":"cn-hangzhou","name":"Hangzhou","type":"city","lat":30.2741,"lng":120.1551,"summary":"Capitale du Zhejiang au bord du lac de l’Ouest : porc Dongpo, thé Longjing, poisson du lac de l’Ouest."},"ing":[["Poitrine de porc avec couenne",800,"g","en 4 carrés"],["Vin de Shaoxing",400,"ml",null],["Sauce soya claire",4,"c. à soupe",null],["Sauce soya foncée",2,"c. à soupe",null],["Sucre candi",50,"g",null],["Ciboules",10,null,null],["Gingembre",50,"g","en tranches"]],"steps":["Blanchir le porc 5 minutes et le ficeler en carrés.","Tapisser une cocotte de ciboules et de gingembre.","Poser le porc couenne en dessous, ajouter vin, sauces et sucre.","Mijoter 2 heures à couvert à feu très doux; retourner couenne au-dessus.","Transférer dans des petits pots et cuire 30 minutes à la vapeur.","Servir avec la sauce réduite."],"photo":{"file":"File:DongPoRou.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fe/DongPoRou.jpg/1280px-DongPoRou.jpg","page":"https://commons.wikimedia.org/wiki/File:DongPoRou.jpg","author":"Sjschen","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"Wikimedia Commons"}},{"slug":"reganmian-wuhan","country":"CN","original":"Règānmiàn (热干面)","title":"Reganmian de Wuhan (nouilles chaudes et sèches à la pâte de sésame)","en":"Wuhan hot dry noodles (reganmian)","es":"Reganmian de Wuhan (fideos calientes y secos)","desc":"Nouilles alcalines précuites et huilées, réchauffées puis enrobées de pâte de sésame, sauce soya, radis mariné et ciboule, petit-déjeuner emblématique de Wuhan.","cat":"Petit-déjeuner","diff":"easy","prep":10,"cook":10,"serv":2,"place":{"slug":"cn-wuhan","name":"Wuhan","type":"city","lat":30.5928,"lng":114.3055,"summary":"Capitale du Hubei sur le Yangzi, célèbre pour ses petits-déjeuners de rue (guozao)."},"ing":[["Nouilles alcalines fraîches",300,"g",null],["Huile de sésame",1,"c. à soupe",null],["Pâte de sésame",3,"c. à soupe",null],["Sauce soya claire",2,"c. à soupe",null],["Sauce soya foncée",1,"c. à thé",null],["Vinaigre",1,"c. à thé",null],["Radis mariné (luobo ding)",2,"c. à soupe","en dés"],["Haricots longs marinés",2,"c. à soupe","en dés"],["Ciboule",2,null,"hachée"],["Huile pimentée",1,"c. à soupe","facultatif"]],"steps":["Cuire les nouilles 1 minute à peine, les égoutter et les enrober d’huile de sésame; étaler pour refroidir.","Délayer la pâte de sésame avec un peu d’huile et d’eau jusqu’à consistance coulante.","Au moment de servir, plonger les nouilles 20 secondes dans l’eau bouillante.","Les égoutter dans un bol.","Ajouter soya, vinaigre, pâte de sésame, légumes marinés et ciboule.","Mélanger vigoureusement et manger chaud."],"photo":{"file":"File:Hot Dry Noodles.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7e/Hot_Dry_Noodles.jpg/1280px-Hot_Dry_Noodles.jpg","page":"https://commons.wikimedia.org/wiki/File:Hot_Dry_Noodles.jpg","author":"ZhengZhou","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"guilin-mifen","country":"CN","original":"Guìlín mǐfěn (桂林米粉)","title":"Nouilles de riz de Guilin (bouillon épicé, porc et cacahuètes)","en":"Guilin rice noodles","es":"Fideos de arroz de Guilin","desc":"Nouilles de riz rondes servies avec une saumure aromatique (lu shui), tranches de bœuf ou porc braisé, cacahuètes frites et haricots marinés, au Guangxi.","cat":"Petit-déjeuner","diff":"medium","prep":20,"cook":90,"serv":4,"place":{"slug":"cn-guilin","name":"Guilin","type":"city","lat":25.2736,"lng":110.29,"summary":"Ville du Guangxi aux pitons karstiques, célèbre pour ses nouilles de riz."},"ing":[["Nouilles de riz rondes",500,"g",null],["Jarret de bœuf ou poitrine de porc",500,"g",null],["Sauce soya",4,"c. à soupe",null],["Badiane, cannelle, réglisse, fenouil",1,"portion",null],["Gingembre",4,"tranches",null],["Cacahuètes",80,"g","frites"],["Haricots longs marinés",80,"g","en dés"],["Ciboule et coriandre",1,"portion",null],["Huile pimentée",2,"c. à soupe",null]],"steps":["Braiser la viande 1 heure 30 dans l’eau avec soya et épices pour obtenir la saumure.","Trancher la viande finement.","Blanchir les nouilles 1 minute.","Les mettre dans les bols avec une louche de saumure.","Garnir de viande, cacahuètes, haricots marinés, ciboule et coriandre.","Ajouter l’huile pimentée et un peu de bouillon d’os si désiré."],"photo":{"file":"File:桂林米粉(Guilin Rice Noodle ).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/e/ed/%E6%A1%82%E6%9E%97%E7%B1%B3%E7%B2%89%28Guilin_Rice_Noodle_%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%A1%82%E6%9E%97%E7%B1%B3%E7%B2%89(Guilin_Rice_Noodle_).jpg","author":"Flickr user gigijin","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}},{"slug":"yangzhou-fried-rice","country":"CN","original":"Yángzhōu chǎofàn (扬州炒饭)","title":"Riz cantonais de Yangzhou (riz sauté aux œufs, crevettes et jambon)","en":"Yangzhou fried rice","es":"Arroz frito de Yangzhou","desc":"Riz de la veille sauté avec œufs, crevettes, jambon, petits pois et ciboule, chaque grain enrobé et séparé, originaire de Yangzhou au Jiangsu.","cat":"Riz","diff":"easy","prep":15,"cook":10,"serv":4,"place":{"slug":"cn-yangzhou","name":"Yangzhou","type":"city","lat":32.3942,"lng":119.4129,"summary":"Ville du Jiangsu sur le Grand Canal, berceau de la cuisine huaiyang et du riz sauté."},"ing":[["Riz cuit de la veille",600,"g",null],["Œufs",3,null,null],["Crevettes décortiquées",150,"g",null],["Jambon cuit",100,"g","en dés"],["Petits pois",80,"g",null],["Champignons noirs",30,"g","réhydratés, hachés"],["Ciboule",3,null,"hachée"],["Huile",3,"c. à soupe",null],["Sel",1,"c. à thé",null],["Poivre blanc",1,"pincée",null]],"steps":["Égrener le riz froid à la main.","Brouiller les œufs dans le wok huilé et les réserver.","Sauter crevettes, jambon, petits pois et champignons 2 minutes.","Ajouter le riz et sauter à feu vif 3 minutes jusqu’à ce que les grains sautent.","Remettre les œufs, saler et poivrer.","Ajouter la ciboule et servir."],"photo":{"file":"File:Yeung Chow Fried Rice in Hong Kong Fast Food Shop.JPG","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/29/Yeung_Chow_Fried_Rice_in_Hong_Kong_Fast_Food_Shop.JPG/1280px-Yeung_Chow_Fried_Rice_in_Hong_Kong_Fast_Food_Shop.JPG","page":"https://commons.wikimedia.org/wiki/File:Yeung_Chow_Fried_Rice_in_Hong_Kong_Fast_Food_Shop.JPG","author":"Ceeseven","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"Wikimedia Commons"}},{"slug":"andong-jjimdak","country":"KR","original":"Andong jjimdak (안동찜닭)","title":"Andong jjimdak (poulet braisé aux nouilles de patate douce)","en":"Andong jjimdak (braised soy chicken with glass noodles)","es":"Andong jjimdak (pollo estofado con fideos de boniato)","desc":"Poulet braisé dans une sauce soya sucrée-piquante avec pommes de terre, carottes, piments séchés et nouilles dangmyeon, né au marché d’Andong.","cat":"Plat principal","diff":"easy","prep":20,"cook":40,"serv":4,"place":{"slug":"kr-andong","name":"Andong","type":"city","lat":36.5684,"lng":128.7294,"summary":"Ville confucéenne du Gyeongsang du Nord : jjimdak, maquereau salé et heotjesatbap."},"ing":[["Poulet",1.2,"kg","en morceaux"],["Nouilles de patate douce (dangmyeon)",100,"g","trempées"],["Pommes de terre",2,null,"en morceaux"],["Carotte",1,null,null],["Oignon",1,null,null],["Piments rouges séchés",4,null,null],["Sauce soya",6,"c. à soupe",null],["Sucre et sirop de maïs",3,"c. à soupe",null],["Ail",6,"gousses",null],["Gingembre",1,"c. à soupe",null],["Piment vert",2,null,null],["Huile de sésame",1,"c. à soupe",null]],"steps":["Blanchir le poulet 3 minutes et rincer.","Le cuire avec 700 ml d’eau, soya, sucre, ail, gingembre et piments séchés 15 minutes.","Ajouter pommes de terre et carotte; cuire 15 minutes.","Ajouter oignon et nouilles égouttées; cuire 5 minutes.","Ajouter piments verts et huile de sésame.","Servir quand les nouilles ont absorbé la sauce brillante."],"photo":{"file":"File:Korean.cuisine-Andong.jjimdalk-03.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/94/Korean.cuisine-Andong.jjimdalk-03.jpg/1280px-Korean.cuisine-Andong.jjimdalk-03.jpg","page":"https://commons.wikimedia.org/wiki/File:Korean.cuisine-Andong.jjimdalk-03.jpg","author":"karendotcom127","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"Wikimedia Commons"}},{"slug":"tteokbokki-seoul","country":"KR","original":"Tteokbokki (떡볶이)","title":"Tteokbokki (bâtonnets de riz en sauce gochujang)","en":"Tteokbokki (spicy rice cakes)","es":"Tteokbokki (pasteles de arroz picantes)","desc":"Bâtonnets de pâte de riz mijotés dans une sauce gochujang sucrée-piquante avec galettes de poisson et œufs durs, en-cas des pojangmacha de Séoul.","cat":"Cuisine de rue","diff":"easy","prep":10,"cook":20,"serv":3,"place":{"slug":"kr-seoul","name":"Séoul","type":"city","lat":37.5665,"lng":126.978,"summary":"Capitale sud-coréenne : tteokbokki de Sindang-dong, marchés de Gwangjang et Namdaemun."},"ing":[["Tteok (bâtonnets de riz)",500,"g",null],["Galettes de poisson (eomuk)",150,"g",null],["Bouillon d’anchois et kombu",500,"ml",null],["Gochujang",3,"c. à soupe",null],["Gochugaru",1,"c. à soupe",null],["Sucre",2,"c. à soupe",null],["Sauce soya",1,"c. à soupe",null],["Ail",2,"gousses",null],["Ciboules",3,null,null],["Œufs durs",3,null,null]],"steps":["Faire tremper les tteok 10 minutes s’ils sont durs.","Porter le bouillon à ébullition avec gochujang, gochugaru, sucre, soya et ail.","Ajouter les tteok et cuire 8 minutes en remuant.","Ajouter les galettes de poisson et les œufs.","Cuire jusqu’à ce que la sauce épaississe et nappe.","Ajouter les ciboules et servir."],"photo":{"file":"File:2015년 10월 25일 과천시 굴다리시장 형태네집 떡볶이2.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ed/2015%EB%85%84_10%EC%9B%94_25%EC%9D%BC_%EA%B3%BC%EC%B2%9C%EC%8B%9C_%EA%B5%B4%EB%8B%A4%EB%A6%AC%EC%8B%9C%EC%9E%A5_%ED%98%95%ED%83%9C%EB%84%A4%EC%A7%91_%EB%96%A1%EB%B3%B6%EC%9D%B42.jpg/1280px-2015%EB%85%84_10%EC%9B%94_25%EC%9D%BC_%EA%B3%BC%EC%B2%9C%EC%8B%9C_%EA%B5%B4%EB%8B%A4%EB%A6%AC%EC%8B%9C%EC%9E%A5_%ED%98%95%ED%83%9C%EB%84%A4%EC%A7%91_%EB%96%A1%EB%B3%B6%EC%9D%B42.jpg","page":"https://commons.wikimedia.org/wiki/File:2015%EB%85%84_10%EC%9B%94_25%EC%9D%BC_%EA%B3%BC%EC%B2%9C%EC%8B%9C_%EA%B5%B4%EB%8B%A4%EB%A6%AC%EC%8B%9C%EC%9E%A5_%ED%98%95%ED%83%9C%EB%84%A4%EC%A7%91_%EB%96%A1%EB%B3%B6%EC%9D%B42.jpg","author":"최광모 (Choe Kwangmo)","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"Wikimedia Commons"}},{"slug":"samgyetang","country":"KR","original":"Samgyetang (삼계탕)","title":"Samgyetang (poussin farci au riz gluant et ginseng)","en":"Samgyetang (ginseng chicken soup)","es":"Samgyetang (sopa de pollo con ginseng)","desc":"Poussin entier farci de riz gluant, ail, jujubes et ginseng, mijoté dans un bouillon clair, consommé pendant les jours les plus chauds de l’été (boknal).","cat":"Soupe","diff":"easy","prep":20,"cook":75,"serv":2,"place":{"slug":"kr-seoul","name":"Séoul","type":"city","lat":37.5665,"lng":126.978,"summary":"Capitale sud-coréenne : tteokbokki de Sindang-dong, marchés de Gwangjang et Namdaemun."},"ing":[["Poussins (coquelets)",2,null,"500 g chacun"],["Riz gluant",100,"g","trempé 1 heure"],["Racines de ginseng frais",2,null,null],["Jujubes séchés",6,null,null],["Ail",10,"gousses",null],["Châtaignes",4,null,"facultatif"],["Eau",2,"l",null],["Ciboule",2,null,"hachée"],["Sel et poivre",1,"portion","à table"]],"steps":["Rincer les poussins et retirer le gras de la cavité.","Les farcir de riz gluant, ail, jujubes, châtaigne et d’un morceau de ginseng.","Croiser les pattes et les fixer en incisant la peau.","Les couvrir d’eau avec le reste de ginseng, d’ail et de jujubes.","Mijoter 1 heure à couvert.","Servir dans le bouillon avec ciboule, sel et poivre à part."],"photo":{"file":"File:KOCIS Korea Malbok Samgyetang 03 (9493375058).jpg","url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/11/KOCIS_Korea_Malbok_Samgyetang_03_%289493375058%29.jpg/1280px-KOCIS_Korea_Malbok_Samgyetang_03_%289493375058%29.jpg","page":"https://commons.wikimedia.org/wiki/File:KOCIS_Korea_Malbok_Samgyetang_03_(9493375058).jpg","author":"Korea.net / Korean Culture and Information Service (Jeon Han)","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"Wikimedia Commons"}}]$batch$::jsonb);
